267.sql:
SELECT `bond_type` 
FROM bond 
WHERE `molecule_id` BETWEEN 'TR000' AND 'TR050';

291.sql:
SELECT COUNT(*) AS answer
FROM molecule
WHERE label = '+';

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

436.sql:
WITH t_distinct AS (
    SELECT DISTINCT c.`id`
    FROM cards c
    JOIN foreign_data fd ON c.uuid = fd.uuid
    WHERE c.`frameEffects` = 'extendedart'
)
SELECT COUNT(*) AS answer FROM t_distinct;
SELECT `id` FROM t_distinct;

617.sql:
SELECT Text
FROM comments
WHERE CreationDate = '2010-07-19 19:37:33.0';

625.sql:
SELECT COUNT(*) AS answer
FROM users
WHERE Location LIKE '%New York%';

857.sql:
WITH final_answer AS (
    SELECT lat, lng
    FROM (
        SELECT DISTINCT name, lat, lng
        FROM (
            SELECT r.name, c.lat, c.lng
            FROM races AS r
            INNER JOIN circuits AS c ON r.circuitId = c.circuitId
            WHERE r.name = 'Abu Dhabi Grand Prix'
        ) AS c_rows
    ) AS t_distinct
)
SELECT * FROM final_answer;

882.sql:
WITH final_answer AS (
    SELECT MIN(year) AS answer
    FROM races
    WHERE name = 'Singapore Grand Prix'
)
SELECT * FROM final_answer;

996.sql:
SELECT COUNT(*) / 11 AS annual_average
FROM races
WHERE date BETWEEN '2000-01-01' AND '2010-12-31';

1035.sql:
SELECT DISTINCT `team_fifa_api_id`
FROM Team_Attributes
WHERE `buildUpPlaySpeed` > 50 AND `buildUpPlaySpeed` < 60;

1213.sql:
WITH final_answer AS (
    SELECT `ID` AS answer
    FROM (
        SELECT DISTINCT `ID`
        FROM (
            SELECT p.`ID`
            FROM Patient AS p
            INNER JOIN Laboratory AS l ON p.`ID` = l.`ID`
            WHERE p.`Birthday` = '1982-04-01' AND l.`ALP` < 300
        )
    )
)
SELECT * FROM final_answer;

1393.sql:
WITH c_cols AS (
    SELECT m.first_name, m.last_name, m.email
    FROM member AS m
    WHERE m.position = 'Secretary'
)
SELECT first_name, last_name, email FROM c_cols;
